INSERT INTO `blog` (`id`, `titulo`, `slug`, `resumen`, `contenido`, `imagen`, `fecha`) VALUES
(1, '¿Lo que comes realmente te nutre?', 'revolucion-suelos-vivos', 'La revolución de los suelos vivos y la nutrición funcional', 'Comer sano no siempre significa estar bien nutrido. Hoy en día consumimos frutas, verduras y hortalizas pensando que aportan todas las vitaminas y minerales que nuestro organismo necesita, pero la realidad científica es otra: <strong>la mayoría de los alimentos actuales han perdido su valor funcional debido al agotamiento del suelo.</strong>\r\n\r\n\r\n\r\nEn el vídeo de hoy reflexionamos sobre esta realidad y te contamos cómo la <b>Agricultura Regenerativa</b> y el estándar <strong>Epigen Healthy Bite</strong> están cambiando las reglas de la alimentación desde el origen: la propia tierra.\r\n\r\n\r\n\r\n\r\n\r\n<h2><strong>Dale al play para ver el vídeo completo y descubrir cómo se transforma la nutrición desde la raíz:</strong>\r\n\r\n\r\n\r\n<video controls src=\"./media/blog/nutricion-funcional.mp4\"></video>\r\n\r\n\r\n\r\n<blockquote><i>«La verdadera nutrición no empieza en tu plato ni en la planta: comienza bajo tierra, en la vida invisible del suelo.»</i></blockquote> \r\n\r\n', './media/blog/epigen-video.png', '2026-07-30 12:55:13');
INSERT INTO `fabricantes` (`id`, `nombre`, `descripcion`, `imagen`, `slug`, `activo`) VALUES
(1, 'Kenogard', 'Fabricante de insumos agrícolas y soluciones de protección fitosanitaria para cultivos', './media/fabricantes/kenogard/kenogard.png', 'kenogard', 'S'),
(2, 'Arvensis', 'Fabricante de insumos agrícolas especializado en nutrición vegetal, bioestimulantes y residuo cero', './media/fabricantes/arvensis/arvensis.png', 'arvensis', 'S'),
(3, 'Viagro', 'Fabricante de insumos agrícolas especializado en soluciones de nutrición técnica y biocontrol', './media/fabricantes/viagro/viagro.png', 'viagro', 'S'),
(4, 'FMC', 'Fabricante de insumos agrícolas enfocado en la sanidad vegetal y tecnologías de protección de cultivos', './media/fabricantes/fmc/fmc.png', 'fmc', 'N'),
(5, 'BASF', 'Fabricante global de insumos agrícolas, productos fitosanitarios y biotecnología para el campo', './media/fabricantes/basf/basf.png', 'basf', 'S'),
(6, 'Seipasa', 'Fabricante de insumos agrícolas especializado en bioinsecticidas, biofungicidas y bioestimulantes de origen natural para una agricultura residuo cero', './media/fabricantes/seipasa/seipasa.webp', 'seipasa', 'N'),
(7, 'Sipcam Inagra', 'Fabricante de insumos agrícolas enfocado en soluciones de protección de cultivos, bioestimulantes y nutrición vegetal integral', './media/fabricantes/sipcam inagra/sipcam-inagra.png', 'sipcam-inagra', 'N'),
(8, 'Inagrosa', 'Fabricante de insumos agrícolas especializado en bioestimulantes, biofertilizantes y soluciones de bionutrición vegetal basadas en aminoácidos y tecnología biológica', './media/fabricantes/inagrosa/inagrosa.png', 'inagrosa', 'N');
INSERT INTO `microorganismos` (`id`, `imagen_bicho_src`, `nombre_bicho`, `descripcion_bicho`, `importancia_beneficios`, `condiciones_campo`) VALUES
(1, './media/microorganismos/es/Achromobacter.png', 'Achromobacter', 'Es un género de bacterias Gram-negativas con forma de bastón y flagelos que le permiten moverse. En la agricultura, destaca como una bacteria promotora del crecimiento vegetal (PGPR) por su capacidad para fijar nitrógeno, solubilizar fósforo y ayudar a las plantas a superar el estrés hídrico o salino.\nAunque <strong>actúa principalmente en el suelo (rizósfera)</strong> —donde vive de forma natural y libera nutrientes—, también tiene la capacidad de <strong>actuar en la parte aérea</strong>. Esto lo logra viajando de forma interna por los vasos de la planta (como endófito) o mediante aplicaciones foliares específicas para frenar el ataque de hongos patógenos en las hojas.\n', '<strong>Promoción del crecimiento y nutrición</strong>: Incrementa la biomasa radicular mediante la fijación biológica de nitrógeno, la solubilización de fósforo insoluble y la síntesis de ácido indolacético (AIA).\r\n • <b>Mitigación del estrés abiótico</b>: Reduce los niveles de etileno endógeno en la raíz mediante la enzima ACC deaminasa, aumentando la tolerancia de la planta a la sequía y la salinidad.\r\n • <b>Acción antagonista y biocontrol</b>: Inhibe y destruye hongos fitopatógenos y nematodos mediante la producción de quitinasas, proteasas y sideróforos.\r\n\r\n<b>Actúa sobre</b>: Hongos del suelo y follaje como <i>Fusarium oxysporum, Rhizoctonia solani</i> y <i>Botrytis cinerea</i>, además de nematodos del género <i>Meloidogyne</i>', ' • <b>Humedad y ambientes acuáticos</b>: Prefiere suelos húmedos, zonas de regadío y sedimentos (entre 60 y 80%).\r\n • <b>Temperatura templada</b>: Su rango óptimo de crecimiento se sitúa entre los <b>25°C</b> y <b>37°C</b>.	\r\n'),
(2, './media/microorganismos/es/Chaetomium_sp.png', 'Chaetomiuum sp.', 'Es un hongo ascomiceto saprófito y celulolítico, caracterizado por sus cuerpos fructíferos (peritecios) recubiertos de pelos.\r\n<b>Actúa eficazmente tanto en el suelo como en la parte aérea</b>. En el suelo, degrada la materia orgánica y protege las raíces en la rizósfera mediante micoparasitismo. En la parte aérea, funciona como endófito o biofungicida foliar, compitiendo por espacio y secretando antibióticos naturales.\r\n', ' • <b>Inducción de resistencia sistémica (ISR)</b>: Estimula los mecanismos de defensa propios de la planta frente a estreses bióticos mediante su comportamiento como endófito en hojas y raíces.\r\n • <b>Micoparasitismo y antibiosis</b>: Secreta enzimas lícitas (glucanasas, quitinasas) y compuestos antifúngicos como la chaetoglobosina, destruyendo físicamente las paredes celulares de los hongos patógenos.\r\n • <b>Biofertilización y degradación de celulosa</b>: Aumenta la disponibilidad de carbono, fosforo y potasio y nutrientes en el suelo al descomponer rápidamente los residuos vegetales de la materia orgánica.\r\n\r\n<b>Actúa sobre</b>: Hongos destructivos del suelo y follaje como <i>Pythium spp., Rhizoctonia solani, Phytophthora spp.</i> y <i>Botrytis cinerea</i>.\r\n', '• <b>Abundancia de celulosa</b>: Requiere restos vegetales ricos en celulosa (paja, rastrojos, madera, estiércol) que utiliza como su alimento principal.\r\n• <b>Temperatura templada a cálida</b>: entre <b>25°C</b> y <b>35°C</b>, aunque algunas son termo tolerantes y aguantan más calor.\r\n• <b>Humedad moderada a alta</b>: Necesita humedad constante en el suelo o sobre los residuos vegetales para activar sus esporas y colonizar (entre 60 y 80%).\r\n• <b>Suelos aireados</b>: Al ser un hongo aeróbico estricto, prefiere las capas superficiales del suelo y terrenos bien oxigenados.'),
(3, './media/microorganismos/es/Diaporthe.png', 'Diaporthe', 'El género <b>Diaporthe</b> pertenece a los ascomicetos e incluye especies con diferentes roles ecológicos: <b>patógenos, endófitos</b> y <b>saprófitos</b>. Muchas especies son conocidas como causantes de enfermedades en cultivos (por ejemplo, Diaporthe phaseolorum en soja), mientras que otras actúan como endófitos beneficiosos, estableciendo asociaciones simbióticas con plantas y mejorando su tolerancia al estrés. \r\n\r\n<b>Actúa principalmente en la parte aérea, aunque posee una alta persistencia en el suelo.</b>', '<b>Producción de metabolitos antifúngicos</b>: Sintetiza compuestos bioactivos únicos (como <i>terpenoides</i> y <i>policétidos</i>) que actúan como potentes antibióticos naturales contra otros hongos.\r\n• <b>Inducción de defensa y tolerancia</b>: Su colonización endófita estimula las vías de resistencia sistémica de la planta, mejorando su respuesta al estrés hídrico y salino.\r\n• <b>Actividad biocontroladora especializada</b>: Protege los tejidos internos de la planta hospedera al competir agresivamente por nicho ecológico contra patógenos invasores.\r\n\r\n<b>Actúa sobre</b>: Frena el crecimiento de hongos fitopatógenos muy agresivos como <b><i>Colletotrichum</i></b> (antracnosis), <b><i>Pestalotiopsis</i></b> y bacterias como <b><i>Staphylococcus aureus</i></b>.\r\n', '• <b>Humedad alta y lluvias</b>: Es el factor crítico; requiere periodos prolongados de lluvias, alta humedad relativa o salpicaduras de agua para dispersar sus esporas. \r\n• <b>Clima templado a cálido</b>: Prospera óptimamente en rangos de temperatura de 20°C a 30°C.\r\n• <b>Restos de cosecha</b>: Sobrevive el invierno fácilmente como saprófito en los residuos vegetales muertos en el suelo esperando la siguiente temporada.\r\n• <b>Retraso en la cosecha</b>: El hongo ataca con más fuerza en las fases finales del cultivo si el ambiente se mantiene húmedo y la recolección se demora.'),
(4, './media/microorganismos/es/Fusarium_Oxysporum.png', 'Fusarium oxysporum', '<b>Fusarium oxysporum no patógeno (FoNP)</b> es una variante saprófita y endófita de este hongo que carece de los genes de virulencia necesarios para causar enfermedad, actuando como un potente agente de biocontrol.\r\n<b>Actúa principalmente en el suelo y en la base radicular, pero sus efectos defensivos se extienden a la parte aérea</b>. En el suelo, coloniza de forma agresiva la rizósfera y la corteza externa de las raíces. Una vez establecido en la zona radicular, bloquea físicamente la entrada de microorganismos dañinos. Desde esta posición, activa las defensas sistémicas de la planta, protegiendo tanto las raíces como el follaje en la parte aérea contra futuras infecciones. Su acción combinada impide el avance de patógenos vasculares antes de que destruyan los haces de transporte de la planta.\r\n', '• <b>Modulación de glucosinolatos radiculares</b>: podría mejorar la resistencia frente a plagas y patógenos o ajustar el metabolismo defensivo de la planta para adaptarse a condiciones de estrés.\r\n• <b>Promoción del crecimiento vegetal</b>: aumentó la biomasa y desarrollo de diferentes especies de Brassica.\r\n• <b>Ciclos de nutrientes</b>: Puede liberar nutrientes mediante secreción de enzimas como celulasas y xilanasas, favoreciendo la fertilidad del suelo.\r\n\r\n<b>Actúa sobre</b>: Inhibe el desarrollo y frena la infección de sus <i>\"hermanos malvados\"</i>, las cepas fitopatógenas de <b><i>Fusarium oxysporum</i></b> (como las que atacan al tomate, plátano o clavel), y reduce el daño de hongos del suelo como <b><i>Verticillium dahliae</i></b> y nematodos del género <b><i>Meloidogyne</b></i>.', 'Para que estas cepas benéficas se establezcan con éxito en el suelo y protejan las raíces, necesitan ciertas condiciones ambientales:\r\n• <b>Temperatura Óptima</b>: Se desarrolla con fuerza en climas templados a cálidos, idealmente entre <b>25 °C</b> y <b>30 °C</b>. \r\n• <b>Humedad del Suelo</b>: Prefiere suelos con humedad moderada a alta. \r\n• <b>Tipo de Suelo</b>: Aunque se adapta a texturas variables, prefiere suelos con buen contenido de <b>materia orgánica</b>.\r\n• <b>pH del Suelo</b>: Su rango ideal de desarrollo es de <b>ligeramente ácido a neutro (pH 5.5 a 7.0)</b>. \r\n'),
(5, './media/microorganismos/es/Metarhizium.png', 'Metarhizium sp.', 'Es un hongo entomopatógeno benéfico, perteneciente al genero Metarhizium, contempla más de 70 especies o aislados. Está ampliamente utilizado en el control biológico de plagas agrícolas.\r\nEstá presente tanto en el suelo como en la parte aérea. Habita de forma natural y prolongada en el <strong>suelo</strong>, donde actúa como un reservorio clave infectando plagas subterráneas. Sin embargo, también se encuentra y aplica en la parte aérea de los cultivos, aunque allí su persistencia es menor debido a la degradación causada por la radiación solar y el calor.\r\n', 'Además de limpiar el campo de insectos dañinos, aporta equilibrio a la tierra:\r\n • Acción contra más de 200 especies (Trips, Largoste, coleoptero,etc.)\r\n • Forma de actuación: coloniza y enferma al insecto huésped; actúa como parasitoide. \r\n • Socio de la Raíz: Convive perfectamente con las raíces (rizósfera), ayudando a mantener un ambiente limpio de microbios malos.\r\n', ' • <b>Temperatura Óptima</b>: Su rango ideal de trabajo está entre los <b>25 °C</b> y <b>30 °C</b>. \r\n • <b>Humedad del suelo</b>: 60–80 % de la capacidad de campo. \r\n • <b>Humedad relativa del aire</b>: ≥ 80 % (óptimo entre 80–95 %). \r\n'),
(6, './media/microorganismos/es/Penicillium_sp.png', 'Penicillium sp.', 'Es un género de hongos ascomicetos saprófitos catalogado como hongo promotor del crecimiento vegetal (PGPF).\r\n<b>Actúa principalmente en el suelo, aunque posee aplicaciones y efectos clave en la parte aérea</b>. En el suelo de la rizósfera, destaca por su alta capacidad para producir ácidos orgánicos que solubilizan el fósforo inorgánico, volviéndolo asimilable para las raíces. En la parte aérea, se utiliza mediante aplicaciones foliares directas activando la Resistencia Sistémica Inducida (RSI) de la planta.\r\n', '<b>Solubilización de fósforo y nutrición</b>: Excreta ácidos orgánicos (como el ácido cítrico y oxálico) en el suelo que rompen los enlaces de fosfatos insolubles, optimizando la nutrición mineral y el desarrollo radicular.\r\n • <b>Promotores del crecimiento vegetal</b>: mediante producción de fitoquímicos, enzimas y hormonas que mejoran el vigor de la planta.\r\n • <b>Fitorremediación y protección frente a contaminantes</b>: ayudan a luchar contra toxicidad por metales pesados en soja, modulando hormonas y proteínas de estrés \r\n • <b>Actúa sobre</b>: Frena y elimina patógenos agresivos del suelo y postcosecha como <b><i>Fusarium oxysporum, Rhizoctonia solani, Pythium spp.</i></b> y <b><i>Botrytis cinerea</i></b> (moho gris).', '• <b>Clima Templado a Fresco</b>: climas templados e incluso tolera temperaturas más frías (óptimo entre <b>20 °C</b> y <b>25 °C</b>, pero sigue activo con menos temperatura).\r\n• <b>Humedad Moderada</b>: Prefiere suelos con humedad constante pero bien aireados. \r\n• <b>Suelos Ácidos a Neutros</b>: Trabaja de forma excelente en rangos de <b>pH de 5.5 a 6.5</b>, donde su capacidad para liberar fósforo es máxima.'),
(7, './media/microorganismos/es/Peribacillus.png', 'Peribacillus', 'Es un género de <b>bacterias</b> baciliformes Gram-positivas, aerobias o anaerobias facultativas, capaces de formar endosporas de alta resistencia.\r\n<b>Actúa de manera altamente eficaz tanto en el suelo como en la parte aérea de las plantas</b>. En el suelo de la rizósfera, opera como una bacteria promotora del crecimiento vegetal (PGPR), sobresaliendo por su capacidad para solubilizar nutrientes y degradar compuestos complejos. En la parte aérea, coloniza con éxito la filósfera y los tejidos internos como endófito, adaptándose a condiciones extremas de temperatura o sequía.\r\n', '<b>Producción de sideróforos y solubilización</b>: Quelata el hierro disponible mediante sideróforos y moviliza fósforo y potasio insolubles, optimizando la nutrición mineral en la rizósfera.\r\n • <b>Tolerancia a estreses térmicos e hídricos</b>: Sintetiza solutos compatibles y compuestos protectores que estabilizan las células vegetales ante heladas, sequías y altas temperaturas.\r\n • <b>Inducción de Resistencia Sistémica (ISR)</b>: Estimula la producción de fitoalexinas y enzimas antioxidantes en la planta, bloqueando el avance de patógenos en raíces y hojas.\r\n\r\n<b>Actúa sobre</b>: Inhibe y destruye hongos y bacterias fitopatógenas como <b><i>Fusarium oxysporum, Rhizoctonia solani, Botrytis cinerea</i></b> y <b><i>Xanthomonas spp</i></b>.\r\n', 'Al ser una bacteria formadora de esporas, es extremadamente resistente, pero trabaja al máximo bajo estas condiciones:\r\n• <b>Temperatura Óptima</b>: Prefiere climas templados a cálidos, desarrollándose de forma ideal entre <b>25 °C</b> y <b>35 °C</b>.\r\n• <b>Supervivencia Extrema (Resistencia)</b>: Puede soportar épocas de sequía severa, heladas o calor extremo \"durmiendo\" en el suelo, y reactivarse inmediatamente cuando vuelve la humedad.\r\n• <b>Humedad del Suelo</b>: Aunque resiste la sequía, para crecer y colonizar activamente las raíces necesita una humedad moderada en el suelo.\r\n'),
(8, './media/microorganismos/es/Pyrenophora.png', 'Pyrenophora gallaeciana', 'Es un hongo ascomiceto fitopatógeno perteneciente a la familia Pleosporaceae, estrechamente ligado a cereales y gramíneas.\r\n<b>Actúa de forma combinada, desarrollándose en la parte aérea, pero dependiendo del suelo para su supervivencia</b>.\r\nEn la zona aérea, infecta agresivamente hojas y espigas, donde produce conidios que causan lesiones necróticas estriadas y tizón foliar. En el suelo, el hongo sobrevive de manera saprófita durante el invierno bajo la forma de pseudotecios ocultos en los rastrojos y restos del cultivo anterior.\r\nAl comenzar la primavera, estas estructuras del suelo liberan ascosporas hacia el aire, iniciando un nuevo ciclo de infección en el follaje.\r\n', '<b>Promotor del crecimiento</b>: P. gallaeciana actúa como endófito beneficioso. Su inoculación aumentó el crecimiento de la planta (biomasa y desarrollo radicular). \r\n• <b>Aceleración del ciclo de nutrientes</b>: Descompone de forma saprófita la celulosa y lignina de los rastrojos secos en el suelo, acelerando la liberación de carbono y minerales para el siguiente cultivo.\r\n• <b>Mejora de la rizosfera</b>: Al producir sideróforos (compuestos quelantes de hierro) y enzimas (celulasas, xilanasas), puede <b>liberar nutrientes atrapados en la materia orgánica o minerales</b>, mejorando la disponibilidad de hierro y fósforo para la planta y el microbiota.\r\n\r\n<b>Actúa sobre</b>: Destruye y controla poblaciones densas de malas hierbas y pastos invasores como el <b>raygrass</b> (<b><i>Lolium spp.</i></b>) y variedades de <b>avena loca</b> o <b<trigo silvestre</b> que compiten con los cultivos principales.\r\n', 'Al ser un hongo adaptado originalmente a los suelos y climas del noroeste peninsular (Galicia), prefiere condiciones específicas: \r\n • <b>Climas Templados y Húmedos</b>: Se desarrolla de forma ideal en zonas con temperaturas suaves y buena disponibilidad de agua, condiciones típicas donde prosperan los cultivos de hoja de invierno y primavera.\r\n • <b>Preferencia por Cultivos de Cruciferas</b>: Aunque puede colonizar otras plantas, su máxima eficacia y su simbiosis perfecta ocurre cuando se asocia con plantas del género Brassica (colza, brócoli, repollo, kale). \r\n • <b>Suelos Saludables</b>: Requiere suelos que mantengan una humedad constante, pero sin llegar a encharcamientos extremos que pudran las raíces donde habita.'),
(9, './media/microorganismos/es/Talaromyces_sp.png', 'Talaromyces sp.', 'Es un género de hongos ascomicetos saprófitos perteneciente a la familia <i>Trichocomaceae</i>, estrechamente emparentado con <i>Penicillium</i>. \r\n<b>Actúa de manera altamente eficaz tanto en el suelo como en la parte aérea de los cultivos</b>. En el suelo de la rizósfera, funciona como un potente hongo promotor del crecimiento vegetal (PGPF), liberando ácidos orgánicos que solubilizan fósforo y hierro. En la parte aérea, se comporta como un endófito protector o biofungicida foliar, colonizando los tejidos y compitiendo agresivamente por espacio frente a patógenos invasores.\r\n', '<b>Solubilización de fósforo y micronutrientes</b>: Secreta ácidos orgánicos de bajo peso molecular que disuelven los fosfatos insolubles y quelatan el hierro, optimizando la nutrición mineral en la rizósfera.\r\n • <b>Micoparasitismo y producción de talaromicina</b>: Produce antibióticos específicos y enzimas hidrolíticas (como quitinasas) que perforan y degradan las paredes celulares de hongos fitopatógenos.\r\n • <b>Inducción de resistencia sistémica (ISR)</b>: Estimula los mecanismos de defensa bioquímicos de la planta, aumentando la producción de fitoalexinas tanto en raíces como en la parte aérea.\r\n\r\n<b>Actúa sobre</b>: Elimina y frena patógenos agresivos del suelo y follaje como <b><i>Verticillium dahliae, Fusarium oxysporum, Rhizoctonia solani</i></b> y <b><i>Colletotrichum spp</i></b>.\r\n', '• <b>Temperaturas Templadas a Cálidas</b>: Su rango óptimo de crecimiento está entre los <b>25 °C</b> y <b>30 °C</b>. \r\n• <b>Suelos Ricos en Materia Orgánica</b>: Al ser un hongo que también puede alimentarse de restos vegetales (saprófito), agradece enormemente la presencia de compost, estiércol o rastrojos para multiplicarse antes de pegarse a la raíz.\r\n• <b>Humedad Constante</b>: Necesita suelos con humedad moderada, el <b>60%</b>.'),
(10, './media/microorganismos/es/Trichoderma_hamatum.png', 'Trichoderma hamatum', 'Es un hongo ascomiceto saprófito y filamentoso benéfico perteneciente a la familia <i>Hypocreaceae</i>, ampliamente reconocido como un potente agente de control biológico (ACB). Se caracteriza técnicamente por su rápida velocidad de crecimiento, su alta capacidad esporulante y su versatilidad para colonizar sustratos orgánicos.\r\n\r\n<b>Actúa de manera altamente eficaz tanto en el suelo como en la parte aérea de las plantas.</b> En el suelo, se establece de forma agresiva en la rizósfera, donde envuelve las raíces y mejora la absorción de nutrientes. En la parte aérea, puede actuar como un endófito que coloniza los tejidos internos del follaje o mediante aplicaciones foliares directas que protegen las hojas contra patógenos invasores.', '<b>Incremento de biomasa y rendimiento: Producción de fitohormonas</b> (como ácido indolacético, AIA) que estimulan el crecimiento radicular y <b>mayor absorción de nutrientes</b>, especialmente nitrógeno y fósforo.\r\n\r\n • <b>Aumento de compuestos de defensa y calidad nutricional : Mayor capacidad antioxidante</b>, lo cual está relacionado con la producción de metabolitos secundarios beneficiosos para la planta y la dieta humana y <b>resistencia natural de la planta frente a plagas y patógenos</b>.\r\n\r\n • <b>Mejora de la estructura y fertilidad del suelo: descomposición de materia orgánica</b>, liberando nutrientes a través de enzimas como <b>celulasas</b> y <b>quitinasas</b>.\r\n\r\n<b>Actúa sobre</b>: Depreda y suprime fitopatógenos agresivos del suelo y madera como <b><i>Rhizoctonia solani, Sclerotinia sclerotiorum, Pythium spp.</i></b> y <b><i>Phytophthora spp</i></b>.', '• <b>Temperatura Óptima</b>: Su rango ideal está entre los <b>20 °C</b> y <b>30 °C</b>. \r\n\r\n• <b>Humedad del Suelo</b>: Le gustan los suelos con buena humedad, entre el <b>60%</b> y el <b>80%</b> (moderada a alta). \r\n\r\n• <b>Materia Orgánica (Su gasolina)</b>: Al ser un hongo que también descompone rastrojos, se multiplica de forma explosiva en suelos ricos en compost, estiércol o humus.\r\n\r\n• <b>pH Tolerante</b>: Se desarrolla perfectamente en un rango amplio de <b>pH (de 5.5 a 7.5)</b>, adaptándose tanto a suelos ligeramente ácidos como neutros.'),
(11, '.media/microorganismos/es/Beauveria_bassiana.png', 'Beauveria bassiana', 'Hongo filamentoso entomopatógeno benéfico del filo Ascomycota (familia Clavicipitaceae). Vive de forma natural en el suelo y actúa infectando insectos por contacto con la cutícula, pero <b>su principal nicho de aplicación y acción comercial es la parte aérea</b> (el follaje de las plantas).', 'No solo regula plagas, también mejora la salud de tu parcela:\r\n • <b>Controlador natural</b>: Tiene la capacidad de actuar sobre una enorme variedad de plagas como <b>Trips</b>, orugas y larva de polilla, <b>mosca blanca</b>, pulgones,…\r\n • <b>Socio de la raíz<b>: Se instala en la zona de las raíces (rizósfera), conviviendo en armonía con bacterias y hongos.\r\n • <b>Reciclador de nutrientes</b>: Al descomponer a los insectos que infecta, libera nutrientes como el <b>nitrógeno</b>, enriqueciendo el suelo.\r\n', 'Para que el hongo sobreviva y aplique toda su fuerza en el cultivo, prefiere estas condiciones:\r\n • <b>El suelo ideal</b>: Suelos francos o franco-arenosos, con buena ventilación y ricos en materia orgánica.\r\n • <b>Humedad en el suelo</b>: Moderada (entre 60% y 80%).\r\n • <n>Humedad en el ambiente</b>: Para que funcione mejor en las hojas, la humedad del aire debe ser <b>mayor al 70-80%</b>.\r\n • <b>Temperatura óptima</b>: Entre >b>20 °C y 30 °C</b>.'),
(12, '.media/microorganismos/es/Pochonia_sp.png', 'Pochonia sp.', 'Es un género de hongos ascomicetos nematófagos facultativos pertenecientes a la familia <i>Clavicipitaceae</i>. <b>Actúa de manera exclusiva y altamente especializada en el suelo de la rizósfera</b>. En este entorno, el hongo sobrevive de forma saprófita y se comporta como un endófito capaz de colonizar las raíces de las plantas sin causarles ningún daño. Su actividad principal se concentra en la interfase suelo-raíz, donde busca, parasita y destruye los huevos y hembras sedentarias de nematodos fitopatógenos.', '<b>Parasitismo de huevos y hembras (Oovicida)</b>: Produce hifas especializadas (<b>apresorios</b>) que perforan mecánicamente y digieren enzimáticamente la cubierta de los huevos y el cuerpo de las hembras de nematodos. • <b>Colonización endófita de la raíz</b>: Se establece en los tejidos corticales radiculares, mejorando la absorción de agua y nutrientes mientras bloquea el acceso a patógenos vasculares. • <b>Inducción de defensas locales</b>: Estimula la producción de enzimas de resistencia (como peroxidasas) en el sistema radicular, limitando la movilidad y éxito de las larvas infectivas. <b>Actúa sobre</b>: Destruye los huevos y nematodos agalladores del género <b><i>Meloidogyne</i></b> (nematodo de la agalla) y nematodos formadores de quistes como <b><i>Globodera spp.</i></b> y <b><i>Heterodera spp</i></b>.', 'Para que las cepas de <i>Pochonia sp.</i> se establezcan con éxito y limpien tu suelo de nematodos, prefiere estas condiciones: • <b>Temperatura Óptima</b>: Trabaja de forma excelente en climas templados y cálidos, idealmente entre <b>22 °C y 30 °C</b>. • <b>Humedad del Suelo</b>: Requiere suelos con humedad constante, entre el <b>60%</b> y el <b>80%</b> (moderada). • <b>Suelos Saludables</b>: Se ve muy beneficiado si el suelo tiene un buen porcentaje de materia orgánica o si se aplica junto con abonos orgánicos (como compost).'),
(13, '.media/microorganismos/es/Aspergillus_Terreus.png', 'Aspergillus Terreus', 'Es un hongo ascomiceto saprófito y filamentosos y benéfico perteneciente a la familia <i>Aspergillaceae</i>, técnicamente reconocido por sus cabezas conidiales columnares de color canela o marrón terroso.\r\n<b>Actúa de manera dual, desarrollándose con éxito tanto en el suelo como en la parte aérea de las plantas</b>. En el suelo, habita la rizosfera donde se comporta como un microorganismo promotor del crecimiento vegetal gracias a su alta capacidad para solubilizar minerales y secretar fitohormonas. En la parte aérea, coloniza los tejidos foliares como hongo endófito y sus conidios se dispersan fácilmente por el aire, confiriéndole protección al follaje contra condiciones de estrés ambiental.\r\n', '<b>Solubilización de fosfatos y producción de auxinas</b>: Sintetiza ácidos orgánicos y la fitohormona ácido indolacético (AIA), estimulando el alargamiento celular de las raíces y optimizando la absorción de nutrientes esenciales.\r\n • <b>Como saprófito</b>, participa en la descomposición de materia orgánica y la estabilización de estructuras del suelo, contribuyendo a los ciclos del carbono y nitrógeno.\r\n • <b>Síntesis de metabolitos antifúngicos</b>: Secreta compuestos bioactivos y ácidos orgánicos que actúan por antibiosis, inhibiendo el crecimiento miceliar y la germinación de esporas rivales en el suelo.\r\n<b>Actúa sobre</b>: Suprime el avance de hongos fitopatógenos destructivos como <b><i>Fusarium oxysporum, Rhizoctonia solani, Pythium spp.</i></b> y <b><i>Sclerotinia sclerotiorum</i></b>.\r\n', '• <b>Calor extremo</b>: Es un hongo termo tolerante que prefiere temperaturas muy altas, con un crecimiento óptimo entre los <b>35°C</b> y <b>40°C</b>.\r\n • <b>Resistencia a la sequía</b>: Requiere poca agua para activarse y prospera fácilmente en suelos áridos o durante periodos secos.\r\n • <b>Suelos ácidos y desgastados</b>: Se desarrolla mejor en suelos con <b>pH ligeramente ácido</b> y compite con éxito en terrenos con pocos nutrientes o bajo carbono.\r\n • <b>Soporta la salinidad</b>: Tolera ambientes muy salinos (hasta un <b>10% de sal</b>), lo que le permite sobrevivir donde otros microorganismos mueren.\r\n');
INSERT INTO `productos` (`id`, `fabricante_id`, `imagen`, `nombre`, `descripcion`, `clasificacion`, `slug`, `sumatorio`, `recuento`) VALUES
(1, 1, './media/fabricantes/kenogard/Dipel_DF.png', 'DIPEL DF', 'DiPel® DF es un insecticida biológico en granulado dispersable en agua con toxinas cristalinas y esporas de Bacillus thuringiensis kurstaki.', 'Inocuo', 'dipel-df', 9.17, 10),
(2, 1, './media/fabricantes/kenogard/Xentari_GD.png', 'XENTARI GD', 'XenTari® GD es un insecticida biológico en gránulos dispersables en agua a base de toxinas cristalinas y esporas de Bacillus thuringiensis subsp. aizawai, especializado en el control selectivo de orugas y orugas difíciles.', 'Inocuo', 'xentari-gd', 9.78, 10),
(3, 1, './media/fabricantes/kenogard/Geoda.png', 'GEODA', 'Geoda® es un fungicida/nematicida biológico formulado a base de microorganismos antagonistas del suelo (Trichoderma / Bacillus), orientado a la protección radicular y prevención de patógenos edáficos.', 'Inocuo', 'geoda', 9.03, 10),
(4, 2, './media/fabricantes/arvensis/ferttybyo.png', 'FERTTYBYO', 'Ferttybyo es un biofertilizante y bioestimulante orgánico formulado a base de consorcios microbianos y extractos de origen vegetal, diseñado para potenciar la actividad rizosférica y la absorción de nutrientes.', 'Afectación Leve', 'ferttybyo', 8.09, 8.33),
(5, 5, './media/fabricantes/basf/velifer.png', 'VELIFER', 'Velifer® es un insecticida/acaricida microbiológico en dispersión oleosa formulado a base de esporas vivas de la cepa fúngica entomopatógena Beauveria bassiana, diseñado para el control de trips, mosca blanca y ácaros.', 'Inocuo', 'velifer', 9.25, 9),
(6, 6, './media/fabricantes/seipasa/pirecris.png', 'PIRECRIS', 'Pirecris® es un insecticida natural en concentrado emulsionable a base de piretrinas naturales extraídas de Chrysanthemum cinerariifolium, formulado con efecto de choque para el control de plagas agrícolas en manejo integrado y ecológico.', 'Inocuo', 'pirecris', 9.92, 10),
(7, 7, './media/fabricantes/sipcam inagra/elio.png', 'ELIO', 'Elio es un bioestimulante y corrector nutricional foliar formulado con complejos orgánicos y microelementos, enfocado en optimizar la floración, el cuajado y la tolerancia al estrés abiótico.', 'Inocuo', 'elio', 9.65, 10),
(8, 3, './media/fabricantes/viagro/brio.png', 'BRIO', 'Brio es un bioestimulante antiestrés y promotor del desarrollo vegetativo formulado a base de aminoácidos libres, extractos de algas y péptidos bioactivos.', 'Inocuo', 'brio', 9.02, 10),
(9, 3, './media/fabricantes/viagro/vitta-k-express.png', 'VITTA K EXPRESS', 'Vitta K Express es un fertilizante foliar líquido de alta concentración en potasio quelatado o complejado, diseñado para una rápida asimilación orientada a mejorar el engorde, maduración y calidad de fruto.', 'Inocuo', 'vitta-k-express', 9.86, 10),
(10, 3, './media/fabricantes/viagro/paramon.png', 'PARAMON', 'Paramon es un bioestimulante fisiológico y activador metabólico formulado a base de fósforo móvil y microelementos, orientado al fortalecimiento de los mecanismos naturales de defensa del cultivo.', 'Afectación Leve', 'paramon', 8.12, 9),
(11, 3, './media/fabricantes/viagro/r-gen.png', 'R-GEN', 'R-Gen es un bioestimulante y regenerador radicular formulado con ácidos húmicos, fúlvicos y reguladores de enraizamiento, diseñado para favorecer la emisión de masa radicular y el establecimiento del cultivo.', 'Afectación Leve', 'r-gen', 8.12, 9),
(12, 3, './media/fabricantes/viagro/radiant.png', 'RADIANT', 'Radiant® es un insecticida de amplio espectro en suspensión concentrada a base de spinetoram, con alta eficacia de contacto e ingestión para el control de trips, orugas y minadores.', 'Afectación Leve', 'radiant', 8.12, 9),
(13, 3, './media/fabricantes/viagro/cu-via.png', 'CU-VIA', 'Cu-Via es una solución líquida de cobre complejado por ácidos orgánicos o lignosulfonatos, formulada para una rápida absorción sistémica y prevención de fisiopatías por carencia de cobre con efecto fitofortificante.', 'Afectación Leve', 'cu-via', 8.59, 10),
(14, 3, './media/fabricantes/viagro/fix.png', 'FIX', 'Fix es un agente coadyuvante tensioactivo, humectante y pegante formulado para mejorar la mojabilidad, adherencia y persistencia de los caldos fitosanitarios y nutricionales.', 'Afectación Leve', 'fix', 8.97, 10);
INSERT INTO `producto_especificaciones` (`id`, `producto_id`, `icono`, `titulo`, `descripcion`) VALUES
(1, 1, 'fas fa-shield-virus', 'Larvicida biológico de alta potencia', 'Formulado a base de toxinas cristalinas y esporas de Bacillus thuringiensis subespecie kurstaki (cepa ABTS-351) en formato granulado dispersable.'),
(2, 1, 'fas fa-bullseye', 'Acción selectiva por ingestión', 'Actúa de forma específica frente a larvas de lepidópteros plaga, las cuales detienen su alimentación a las pocas horas de ingerir el producto.'),
(3, 1, 'fas fa-dove', 'Respeto absoluto por la fauna auxiliar', 'Inocuo para insectos beneficiosos y mamíferos, lo que lo convierte en una herramienta fundamental e insustituible en los programas de manejo integrado de plagas.'),
(4, 2, 'fas fa-microscope', 'Tecnología microbiana selectiva', 'Desarrollado bajo estrictos estándares microbiológicos para el control de poblaciones de insectos plaga específicos en los programas fitosanitarios.'),
(5, 2, 'fas fa-project-diagram', 'Perfecta integración en estrategias IPM', 'Compatible con las pautas de control integrado y rotación de materias activas para prevenir la aparición de resistencias en campo.'),
(6, 2, 'fas fa-hand-holding-water', 'Formulación de fácil aplicación', 'Presentado en granulación optimizada para conseguir una excelente suspensión en el caldo de pulverización y una distribución homogénea sobre el follaje.'),
(7, 3, 'fas fa-biohazard', 'Doble concentración depurada', 'Insecticida biológico en polvo mojable formulado a partir de una cepa avanzada de Bacillus thuringiensis a doble concentración, aportando mayor potencia y persistencia.'),
(8, 3, 'fas fa-stopwatch', 'Cero días de plazo de seguridad', 'Al no dejar ningún tipo de residuo químico en las cosechas, permite realizar tratamientos eficaces incluso hasta el mismo día de la recolección.'),
(9, 3, 'fas fa-seedling', 'Ideal para agricultura ecológica', 'Diseñado para el control riguroso de orugas y lepidópteros defoliadores o frutícolas en una amplísima variedad de cultivos hortícolas, frutales y leñosos.'),
(10, 4, 'fas fa-seedling', 'Nutrición boratada avanzada', 'Formulación líquida a base de boro acomplejado con etanolamina, diseñada para optimizar la absorción del nutriente como ácido bórico directamente en los tejidos vegetales.'),
(11, 4, 'fas fa-spa', 'Estímulo de floración y cuajado', 'Interviene de forma directa en el crecimiento meristemático, promoviendo la fecundación óptima, regulando la división celular y previniendo malformaciones en brotes, flores y frutos.'),
(12, 4, 'fas fa-check-circle', 'Apto para agricultura ecológica', 'Producto certificado e integrado para su uso en sistemas de producción ecológica, garantizando la máxima seguridad y respeto por el desarrollo fisiológico del cultivo.'),
(13, 5, 'fas fa-bug', 'Bioinsecticida de cepa exclusiva', 'Basado en la exclusiva cepa PPRI 5339 de Beauveria bassiana de BASF, ofrece una alta eficacia intrínseca y gran capacidad de infección por contacto directo sobre la cutícula del insecto.'),
(14, 5, 'fas fa-shield-alt', 'Control eficaz de mosca blanca y trips', 'Solución biológica especializada en reducir de forma persistente las poblaciones de trips y mosca blanca en cultivos protegidos, hortícolas y ornamentales.'),
(15, 5, 'fas fa-leaf', 'Compatible con gestión integrada y residuo cero', 'Su formulación avanzada respeta a la fauna auxiliar y a los polinizadores, ayudando a minimizar los residuos químicos en la cosecha y cumpliendo los estándares de la cadena alimentaria.'),
(16, 6, 'fas fa-bolt', 'Potente efecto de choque (Knock down)', 'Insecticida agrícola natural que provoca una rápida eliminación y desactivación de las poblaciones de insectos plaga tras su aplicación.'),
(17, 6, 'fas fa-bug', 'Control de pulgón, mosca blanca y cicadélidos', 'Amplio espectro de acción altamente eficaz frente a insectos de cuerpo blando como mosca blanca, pulgones y mosquito verde en vid y hortícolas.'),
(18, 6, 'fas fa-clock', '100% Natural sin plazos de seguridad amplios', 'Formulación patentada a base de extractos vegetales sin residuo químico ni PBO, permitiendo realizar tratamientos muy próximos al momento de la recolección.'),
(19, 7, 'fas fa-shield-alt', 'Fungicida anti-oídio de alta persistencia', 'Especialidad a base de Ciflufenamid 10% con actividad preventiva, curativa, translaminar y efecto vapor para un control duradero.'),
(20, 7, 'fas fa-sync', 'Nueva familia química anti-resistencias', 'Actúa alterando la formación de haustorios y esporulación del hongo, constituyendo una herramienta excelente en rotación para evitar resistencias.'),
(21, 7, 'fas fa-award', 'Gama Cultivo Zero y Residuo Mínimo', 'Destaca por su perfil de degradación rápido, corto plazo de seguridad y total compatibilidad con insectos auxiliares y polinizadores.'),
(22, 8, 'fas fa-dna', 'Innovador prebiótico para el suelo', 'Formulado avanzado de origen biotecnológico diseñado para estimular de forma selectiva la microbiota nativa beneficiosa y potenciar el microbioma del suelo.'),
(23, 8, 'fas fa-globe-africa', 'Pionero en agricultura regenerativa', 'Reconocido por su capacidad para reactivar la fertilidad biológica y la estructura productiva de los suelos agrícolas degradados.'),
(24, 8, 'fas fa-shield-virus', 'Resistencia sistémica y estrés biótico', 'Ayuda a los cultivos a tolerar y mitigar afecciones fitopatológicas complejas, mejorando la resiliencia natural de la planta frente a virus y patógenos.'),
(25, 9, 'fas fa-bolt', 'Corrector potásico de acción ultra rápida', 'Fuente de potasio de máxima disponibilidad inmediata para el cultivo, formulada para cubrir picos de alta demanda nutricional.'),
(26, 9, 'fas fa-weight-hanging', 'Especial para maduración y engorde', 'Acelera de forma natural los procesos de acumulación de azúcares, coloración, tamaño y consistencia óptima de los frutos.'),
(27, 9, 'fas fa-water', 'Eficiencia osmótica e hídrica', 'Mejora la regulación de los estomas y la gestión interna del agua, dotando al cultivo de mayor resistencia frente a la sequía o salinidad.'),
(28, 10, 'fas fa-shield-alt', 'Escudo protector nutricional', 'Formulado bioestimulante diseñado para robustecer las paredes celulares y las barreras mecánicas naturales de los tejidos vegetales.'),
(29, 10, 'fas fa-sync-alt', 'Activación metabólica integral', 'Estimula las rutas metabólicas internas de la planta para propiciar una respuesta rápida y coordinada frente a condiciones adversas.'),
(30, 10, 'fas fa-leaf', 'Sinergia con la sanidad del cultivo', 'Complemento ideal en estrategias de manejo integrado para mantener la vitalidad de la planta sin alterar sus procesos biológicos esenciales.'),
(31, 11, 'fas fa-seedling', 'Bioestimulante de regeneración celular', 'Solución avanzada enfocada en reactivar los meristemos y acelerar la recuperación de tejidos vegetales dañados o sometidos a fuerte estrés.'),
(32, 11, 'fas fa-hands-helping', 'Estimulación radicular y foliar', 'Promueve un crecimiento vigoroso tanto del sistema de raíces como de la parte aérea, optimizando la superficie fotosintética útil.'),
(33, 11, 'fas fa-apple-alt', 'Maximización del potencial productivo', 'Contribuye de manera decisiva a un mejor cuajado, engorde uniforme y mayor calidad organoléptica en los frutos recolectados.'),
(34, 12, 'fas fa-sun', 'Potenciador de la actividad fotosintética', 'Complejo nutricional y bioestimulante destinado a optimizar la captación de energía lumínica y la transformación de azúcares en la planta.'),
(35, 12, 'fas fa-magic', 'Calidad y brillo en la cosecha', 'Mejora ostensiblemente los aspectos visuales, el color, el aspecto comercial y los grados Brix de los frutos de alto valor económico.'),
(36, 12, 'fas fa-check', 'Compatibilidad y rápida absorción', 'Formulación altamente soluble diseñada para integrarse sin problemas en cualquier plan de fertirrigación o aplicación foliar.'),
(37, 13, 'fas fa-atom', 'Nutrición cúprica de alta eficiencia', 'Solución nutricional a base de cobre complejado o formulado para corregir carencias específicas y potenciar las defensas naturales del cultivo.'),
(38, 13, 'fas fa-tint', 'Máxima disolución y asimilación', 'Diseñado para una rápida absorción sistémica y foliar, evitando precipitaciones en el tanque y maximizando el aprovechamiento por parte de la planta.'),
(39, 13, 'fas fa-seedling', 'Soporte metabólico y protector', 'Favorece la activación de múltiples enzimas clave en los procesos respiratorios y de síntesis de proteínas del vegetal en momentos de alta humedad.'),
(40, 14, 'fas fa-sliders-h', 'Regulador del crecimiento y desarrollo', 'Especialidad agronómica orientada a equilibrar la balanza hormonal de la planta, optimizando la brotación, el desarrollo vegetativo y el engorde del fruto.'),
(41, 14, 'fas fa-chart-line', 'Optimización de la cosecha', 'Mejora de forma homogénea parámetros cualitativos clave como el calibre, la consistencia y los estándares comerciales de la producción final.'),
(42, 14, 'fas fa-bolt', 'Mitigación del estrés ambiental', 'Ayuda a superar con éxito situaciones de estrés abiótico (golpes de calor, salinidad o desequilibrios hídricos) manteniendo el ritmo productivo.');
