(177, 'fabricantes', 6, 'descripcion', 'en', 'Manufacturer of agricultural inputs specialized in bioinsecticides, biofungicides and biostimulants of natural origin for zero waste agriculture'),
(178, 'fabricantes', 6, 'descripcion', 'pt', 'Fabricante de insumos agrícolas especializada em bioinseticidas, biofungicidas e bioestimulantes de origem natural para uma agricultura com desperdício zero'),
(179, 'fabricantes', 6, 'descripcion', 'fr', 'Fabricant d´intrants agricoles spécialisé en bioinsecticides, biofongicides et biostimulants d´origine naturelle pour une agriculture zéro déchet'),
(180, 'fabricantes', 6, 'descripcion', 'ca', 'Fabricant d´insums agrícoles especialitzat en bioinsecticides, biofungicides i bioestimulants d´origen natural per a una agricultura residu zero'),
(181, 'fabricantes', 7, 'descripcion', 'en', 'Agricultural input manufacturer focused on crop protection solutions, biostimulants and comprehensive plant nutrition'),
(182, 'fabricantes', 7, 'descripcion', 'pt', 'Fabricante de insumos agrícolas focado em soluções de proteção de cultivos, bioestimulantes e nutrição vegetal abrangente'),
(183, 'fabricantes', 7, 'descripcion', 'fr', 'Fabricant d´intrants agricoles axé sur les solutions de protection des cultures, les biostimulants et la nutrition complète des plantes'),
(184, 'fabricantes', 7, 'descripcion', 'ca', 'Fabricant d´insums agrícoles enfocat a solucions de protecció de cultius, bioestimulants i nutrició vegetal integral'),
(185, 'fabricantes', 8, 'descripcion', 'en', 'Manufacturer of agricultural inputs specialized in biostimulants, biofertilizers and plant bionutrition solutions based on amino acids and biological technology'),
(186, 'fabricantes', 8, 'descripcion', 'pt', 'Fabricante de insumos agrícolas especializada em bioestimulantes, biofertilizantes e soluções de bionutrição vegetal baseadas em aminoácidos e tecnologia biológica'),
(187, 'fabricantes', 8, 'descripcion', 'fr', 'Fabricant d´intrants agricoles spécialisé en biostimulants, biofertilisants et solutions de bionutrition végétale à base d´acides aminés et de technologie biologique'),
(188, 'fabricantes', 8, 'descripcion', 'ca', 'Fabricant d´insums agrícoles especialitzat en bioestimulants, biofertilitzants i solucions de bionutrició vegetal basades en aminoàcids i tecnologia biològica'),
(189, 'productos', 1, 'descripcion', 'en', 'DiPel® DF is a water-dispersible granule biological insecticide containing crystalline toxins and spores of Bacillus thuringiensis kurstaki.'),
(190, 'productos', 1, 'descripcion', 'pt', 'O DiPel® DF é um inseticida biológico em grânulos dispersíveis em água que contém toxinas cristalinas e esporos de Bacillus thuringiensis kurstaki.'),
(191, 'productos', 1, 'descripcion', 'fr', 'DiPel® DF est un insecticide biologique sous forme de granulés dispersibles dans l\'eau, contenant des toxines cristallines et des spores de Bacillus thuringiensis kurstaki.'),
(192, 'productos', 1, 'descripcion', 'ca', 'DiPel® DF és un insecticida biològic en forma de grànuls dispersables en aigua que conté toxines cristal·lines i espores de Bacillus thuringiensis kurstaki.'),
(193, 'productos', 2, 'descripcion', 'en', 'XenTari® GD is a biological insecticide in water-dispersible granules based on crystalline toxins and spores of Bacillus thuringiensis subsp. aizawai, specialized in the selective control of caterpillars and difficult caterpillars.'),
(194, 'productos', 2, 'descripcion', 'pt', 'XenTari® GD é um inseticida biológico em grânulos dispersíveis em água à base de toxinas cristalinas e esporos de Bacillus thuringiensis subsp. aizawai, especializada no controle seletivo de lagartas e lagartas difíceis.'),
(195, 'productos', 2, 'descripcion', 'fr', 'XenTari® GD est un insecticide biologique en granulés hydrodispersables à base de toxines cristallines et de spores de Bacillus thuringiensis subsp. aizawai, spécialisée dans le contrôle sélectif des chenilles et des chenilles difficiles.'),
(196, 'productos', 2, 'descripcion', 'ca', 'XenTari® GD és un insecticida biològic en grànuls dispersables en aigua a base de toxines cristal·lines i espores de Bacillus thuringiensis subsp. aizawai, especialitzat en el control selectiu d\'erugues i erugues difícils.'),
(197, 'productos', 3, 'descripcion', 'en', 'Geoda® is a biological fungicide/nematicide formulated from soil antagonist microorganisms (Trichoderma / Bacillus), aimed at root protection and prevention of soil pathogens.'),
(198, 'productos', 3, 'descripcion', 'pt', 'Geoda® é um fungicida/nematicida biológico formulado a partir de microrganismos antagonistas do solo (Trichoderma / Bacillus), voltado para proteção radicular e prevenção de patógenos do solo.'),
(199, 'productos', 3, 'descripcion', 'fr', 'Geoda® est un fongicide/nématicide biologique formulé à partir de micro-organismes antagonistes du sol (Trichoderma / Bacillus), destiné à la protection des racines et à la prévention des pathogènes du sol.'),
(200, 'productos', 3, 'descripcion', 'ca', 'Geoda® és un fungicida/nematicida biològic formulat a base de microorganismes antagonistes del sòl (Trichoderma / Bacillus), orientat a la protecció radicular i prevenció de patògens edàfics.'),
(201, 'productos', 4, 'descripcion', 'en', 'Ferttybyo is an organic biofertilizer and biostimulant formulated from microbial consortia and extracts of plant origin, designed to enhance rhizospheric activity and nutrient absorption.'),
(202, 'productos', 4, 'descripcion', 'pt', 'Ferttybyo é um biofertilizante e bioestimulante orgânico formulado a partir de consórcios microbianos e extratos de origem vegetal, desenvolvido para aumentar a atividade rizosférica e a absorção de nutrientes.'),
(203, 'productos', 4, 'descripcion', 'fr', 'Ferttybyo est un biofertilisant organique et biostimulant formulé à partir de consortiums microbiens et d´extraits d´origine végétale, conçu pour améliorer l´activité rhizosphérique et l´absorption des nutriments.'),
(204, 'productos', 4, 'descripcion', 'ca', 'Ferttybyo és un biofertilitzant i bioestimulant orgànic formulat amb consorcis microbians i extractes d´origen vegetal, dissenyat per potenciar l´activitat rizosfèrica i l´absorció de nutrients.'),
(205, 'productos', 5, 'descripcion', 'en', 'Velifer® is a microbiological insecticide/acaricide in oily dispersion formulated with live spores of the entomopathogenic fungal strain Beauveria bassiana, designed for the control of thrips, whiteflies and mites.'),
(206, 'productos', 5, 'descripcion', 'pt', 'Velifer® é um inseticida/acaricida microbiológico em dispersão oleosa formulado com esporos vivos da cepa fúngica entomopatogênica Beauveria bassiana, desenvolvido para o controle de tripes, moscas brancas e ácaros.'),
(207, 'productos', 5, 'descripcion', 'fr', 'Velifer® est un insecticide/acaricide microbiologique en dispersion huileuse formulé à base de spores vivantes de la souche fongique entomopathogène Beauveria bassiana, conçu pour lutter contre les thrips, les aleurodes et les acariens.'),
(208, 'productos', 5, 'descripcion', 'ca', 'Velifer® és un insecticida/acaricida microbiològic en dispersió oliosa formulat a base d\'espores vives del cep fúngic entomopatògen Beauveria bassiana, dissenyat per al control de trips, mosca blanca i àcars.'),
(209, 'productos', 6, 'descripcion', 'en', 'Pirecris® is a natural insecticide in an emulsifiable concentrate based on natural pyrethrins extracted from Chrysanthemum cinerariifolium, formulated with a shock effect for the control of agricultural pests in integrated and ecological management.'),
(210, 'productos', 6, 'descripcion', 'pt', 'Pirecris® é um inseticida natural em concentrado emulsionável à base de piretrinas naturais extraídas de Chrysanthemum cinerariifolium, formulado com efeito de choque para o controle de pragas agrícolas em manejo integrado e ecológico.'),
(211, 'productos', 6, 'descripcion', 'fr', 'Pirecris® est un insecticide naturel en concentré émulsionnable à base de pyréthrines naturelles extraites de Chrysanthemum cinerariifolium, formulé avec un effet choc pour la lutte contre les ravageurs agricoles en gestion intégrée et écologique.'),
(212, 'productos', 6, 'descripcion', 'ca', 'Pirecris® és un insecticida natural en concentrat emulsionable a base de piretrines naturals extretes de Chrysanthemum cinerariifolium, formulat amb efecte de xoc per al control de plagues agrícoles en maneig integrat i ecològic.'),
(213, 'productos', 7, 'descripcion', 'en', 'Elio is a biostimulant and foliar nutritional corrector formulated with organic complexes and microelements, focused on optimizing flowering, fruit set and tolerance to abiotic stress.'),
(214, 'productos', 7, 'descripcion', 'pt', 'Elio é um bioestimulante e corretor nutricional foliar formulado com complexos orgânicos e microelementos, com foco na otimização da floração, frutificação e tolerância ao estresse abiótico.'),
(215, 'productos', 7, 'descripcion', 'fr', 'Elio est un correcteur nutritionnel biostimulant et foliaire formulé à base de complexes organiques et de microéléments, axé sur l\'optimisation de la floraison, de la nouaison et de la tolérance au stress abiotique.'),
(216, 'productos', 7, 'descripcion', 'ca', 'Elio és un bioestimulant i corrector nutricional foliar formulat amb complexos orgànics i microelements, enfocat a optimitzar la floració, el quallat i la tolerància a l\'estrès abiòtic.'),
(217, 'productos', 8, 'descripcion', 'en', 'Brio is an anti-stress biostimulant and promoter of vegetative development formulated with free amino acids, algae extracts and bioactive peptides.'),
(218, 'productos', 8, 'descripcion', 'pt', 'Brio é um bioestimulante antiestresse e promotor do desenvolvimento vegetativo formulado com aminoácidos livres, extratos de algas e peptídeos bioativos.'),
(219, 'productos', 8, 'descripcion', 'fr', 'Brio est un biostimulant anti-stress et promoteur du développement végétatif formulé à base d\'acides aminés libres, d\'extraits d\'algues et de peptides bioactifs.'),
(220, 'productos', 8, 'descripcion', 'ca', 'Brio és un bioestimulant antiestrès i promotor del desenvolupament vegetatiu formulat a base d\'aminoàcids lliures, extractes d\'algues i pèptids bioactius.'),
(221, 'productos', 9, 'descripcion', 'en', 'Vitta K Express is a liquid foliar fertilizer with a high concentration of chelated or complexed potassium, designed for rapid assimilation aimed at improving fattening, ripening and fruit quality.'),
(222, 'productos', 9, 'descripcion', 'pt', 'Vitta K Express é um fertilizante foliar líquido com alta concentração de potássio quelado ou complexado, desenvolvido para rápida assimilação visando melhorar a engorda, o amadurecimento e a qualidade dos frutos.'),
(223, 'productos', 9, 'descripcion', 'fr', 'Vitta K Express est un engrais foliaire liquide à haute concentration en potassium chélaté ou complexé, conçu pour une assimilation rapide visant à améliorer l\'engraissement, la maturation et la qualité des fruits.'),
(224, 'productos', 9, 'descripcion', 'ca', 'Vitta K Express és un fertilitzant foliar líquid d\'alta concentració en potassi quelat o complexat, dissenyat per a una ràpida assimilació orientada a millorar l\'engreix, la maduració i la qualitat de fruit.'),
(225, 'productos', 10, 'descripcion', 'en', 'Paramon is a physiological biostimulant and metabolic activator formulated with mobile phosphorus and microelements, aimed at strengthening the crop\'s natural defense mechanisms.'),
(226, 'productos', 10, 'descripcion', 'pt', 'Paramon é um bioestimulante fisiológico e ativador metabólico formulado com fósforo móvel e microelementos, que visa fortalecer os mecanismos naturais de defesa da cultura.'),
(227, 'productos', 10, 'descripcion', 'fr', 'Paramon est un biostimulant physiologique et activateur métabolique formulé à base de phosphore mobile et de microéléments, visant à renforcer les mécanismes de défense naturels de la culture.'),
(228, 'productos', 10, 'descripcion', 'ca', 'Paramon és un bioestimulant fisiològic i activador metabòlic formulat a base de fòsfor mòbil i microelements, orientat a l\'enfortiment dels mecanismes naturals de defensa del cultiu.'),
(229, 'productos', 11, 'descripcion', 'en', 'R-Gen is a biostimulant and root regenerator formulated with humic and fulvic acids and rooting regulators, designed to promote the emission of root mass and the establishment of the crop.'),
(230, 'productos', 11, 'descripcion', 'pt', 'R-Gen é um bioestimulante e regenerador de raízes formulado com ácidos húmicos e fúlvicos e reguladores de enraizamento, desenvolvido para promover a emissão de massa radicular e o estabelecimento da cultura.'),
(231, 'productos', 11, 'descripcion', 'fr', 'R-Gen est un biostimulant et régénérateur de racines formulé avec des acides humiques et fulviques et des régulateurs d\'enracinement, conçu pour favoriser l\'émission de masse racinaire et l\'établissement de la culture.'),
(232, 'productos', 11, 'descripcion', 'ca', 'R-Gen és un bioestimulant i regenerador radicular formulat amb àcids húmics, fúlvics i reguladors d\'arrelament dissenyat per afavorir l\'emissió de massa radicular i l\'establiment del cultiu.'),
(233, 'productos', 12, 'descripcion', 'en', 'Radiant® is a broad-spectrum insecticide in concentrated suspension based on spinetoram, with high contact and ingestion effectiveness for the control of thrips, caterpillars and leafminers.'),
(234, 'productos', 12, 'descripcion', 'pt', 'Radiant® é um inseticida de amplo espectro em suspensão concentrada à base de espinetoram, com alta eficácia de contato e ingestão para o controle de tripes, lagartas e minadores.'),
(235, 'productos', 12, 'descripcion', 'fr', 'Radiant® est un insecticide à large spectre en suspension concentrée à base de spinétorame, à haute efficacité de contact et d\'ingestion pour le contrôle des thrips, des chenilles et des mineuses.'),
(236, 'productos', 12, 'descripcion', 'ca', 'Radiant® és un insecticida d\'ampli espectre en suspensió concentrada amb spinetoram, amb alta eficàcia de contacte i ingestió per al control de trips, erugues i minadors.'),
(237, 'productos', 13, 'descripcion', 'en', 'Cu-Via is a liquid solution of copper complexed with organic acids or lignosulfonates, formulated for rapid systemic absorption and prevention of physiopathies due to copper deficiency with a phytofortifying effect.'),
(238, 'productos', 13, 'descripcion', 'pt', 'Cu-Via é uma solução líquida de cobre complexado com ácidos orgânicos ou lignossulfonatos, formulada para rápida absorção sistêmica e prevenção de fisiopatias por deficiência de cobre com efeito fitofortificante.'),
(239, 'productos', 13, 'descripcion', 'fr', 'Cu-Via est une solution liquide de cuivre complexée avec des acides organiques ou des lignosulfonates, formulée pour une absorption systémique rapide et la prévention des physiopathies dues à une carence en cuivre avec un effet phytofortifiant.'),
(240, 'productos', 13, 'descripcion', 'ca', 'Cu-Via és una solució líquida de coure complexat per àcids orgànics o lignosulfonats, formulada per a una ràpida absorció sistèmica i prevenció de fisiopaties per carència de coure amb efecte fitofortificant.'),
(241, 'productos', 14, 'descripcion', 'en', 'Fix is a surfactant, humectant and adhesive adjuvant agent formulated to improve the wettability, adhesion and persistence of phytosanitary and nutritional broths.'),
(242, 'productos', 14, 'descripcion', 'pt', 'Fix é um agente tensoativo, umectante e adjuvante adesivo formulado para melhorar a molhabilidade, adesão e persistência de caldos fitossanitários e nutricionais.'),
(243, 'productos', 14, 'descripcion', 'fr', 'Fix est un agent tensioactif, humectant et adjuvant adhésif formulé pour améliorer la mouillabilité, l\'adhésion et la persistance des bouillons phytosanitaires et nutritionnels.'),
(244, 'productos', 14, 'descripcion', 'ca', 'Fix és un agent coadjuvant tensioactiu, humectant i pegant formulat per millorar la mullabilitat, adherència i persistència dels vins fitosanitaris i nutricionals.'),
