(365, 'producto_especificaciones', 1, 'titulo', 'en', 'High potency biological larvicide'),
(366, 'producto_especificaciones', 1, 'titulo', 'pt', 'Larvicida biológico de alta potência'),
(367, 'producto_especificaciones', 1, 'titulo', 'fr', 'Larvicide biologique à haute puissance'),
(368, 'producto_especificaciones', 1, 'titulo', 'ca', 'Larvicida biològic d\'alta potència'),
(369, 'producto_especificaciones', 1, 'descripcion', 'en', 'Formulated based on crystalline toxins and spores of Bacillus thuringiensis subspecies kurstaki (strain ABTS-351) in a water-dispersible granule format.'),
(370, 'producto_especificaciones', 1, 'descripcion', 'pt', 'Formulado à base de toxinas cristalinas e esporos de Bacillus thuringiensis subespécie kurstaki (estirpe ABTS-351) em formato de grânulos dispersíveis.'),
(371, 'producto_especificaciones', 1, 'descripcion', 'fr', 'Formulé à base de toxines cristallines et de spores de Bacillus thuringiensis sous-espèce kurstaki (souche ABTS-351) sous forme de granulés dispersables.'),
(372, 'producto_especificaciones', 1, 'descripcion', 'ca', 'Formulat a base de toxines cristal·lines i espores de Bacillus thuringiensis subespècie kurstaki (cepa ABTS-351) en format granulat dispersable.'),
(373, 'producto_especificaciones', 2, 'titulo', 'en', 'Selective action by ingestion'),
(374, 'producto_especificaciones', 2, 'titulo', 'pt', 'Ação seletiva por ingestão'),
(375, 'producto_especificaciones', 2, 'titulo', 'fr', 'Action sélective par ingestion'),
(376, 'producto_especificaciones', 2, 'titulo', 'ca', 'Acció selectiva per ingestió'),
(377, 'producto_especificaciones', 2, 'descripcion', 'en', 'It acts specifically against pest lepidopteran larvae, which stop feeding within a few hours of ingesting the product.'),
(378, 'producto_especificaciones', 2, 'descripcion', 'pt', 'Atua especificamente contra larvas de lepidópteros praga, as quais param de se alimentar poucas horas após ingerirem o produto.'),
(379, 'producto_especificaciones', 2, 'descripcion', 'fr', 'Il agit spécifiquement contre les larves de lépidoptères nuisibles, qui cessent de s’alimenter quelques heures après avoir ingéré le produit.'),
(380, 'producto_especificaciones', 2, 'descripcion', 'ca', 'Actua de manera específica contra larves de lepidòpters plaga, les quals aturen la seva alimentació a les poques hores d’ingerir el producte.'),
(381, 'producto_especificaciones', 3, 'titulo', 'en', 'Absolute respect for beneficial fauna'),
(382, 'producto_especificaciones', 3, 'titulo', 'pt', 'Respeito absoluto pela fauna auxiliar'),
(383, 'producto_especificaciones', 3, 'titulo', 'fr', 'Respect absolu de la faune auxiliaire'),
(384, 'producto_especificaciones', 3, 'titulo', 'ca', 'Respecte absolut per la fauna auxiliar'),
(385, 'producto_especificaciones', 3, 'descripcion', 'en', 'Harmless to beneficial insects and mammals, making it a fundamental and irreplaceable tool in integrated pest management programs.'),
(386, 'producto_especificaciones', 3, 'descripcion', 'pt', 'Inócuo para insetos benéficos e mamíferos, o que o torna uma ferramenta fundamental e insubstituível nos programas de manejo integrado de pragas.'),
(387, 'producto_especificaciones', 3, 'descripcion', 'fr', 'Inoffensif pour les insectes utiles et les mammifères, ce qui en fait un outil fondamental et irremplaçable dans les programmes de lutte intégrée contre les ravageurs.'),
(388, 'producto_especificaciones', 3, 'descripcion', 'ca', 'Innocu per a insectes benèfics i mamífers, la qual cosa el converteix en una eina fonamental i insubstituïble en els programes de gestió integrada de plagues.'),
(389, 'producto_especificaciones', 4, 'titulo', 'en', 'Selective microbial technology'),
(390, 'producto_especificaciones', 4, 'titulo', 'pt', 'Tecnologia microbiana seletiva'),
(391, 'producto_especificaciones', 4, 'titulo', 'fr', 'Technologie microbienne sélective'),
(392, 'producto_especificaciones', 4, 'titulo', 'ca', 'Tecnologia microbiana selectiva'),
(393, 'producto_especificaciones', 4, 'descripcion', 'en', 'Developed under strict microbiological standards for the control of specific pest insect populations in phytosanitary programs.'),
(394, 'producto_especificaciones', 4, 'descripcion', 'pt', 'Desenvolvido sob rigorosos padrões microbiológicos para o controle de populações de insetos praga específicos em programas fitossanitários.'),
(395, 'producto_especificaciones', 4, 'descripcion', 'fr', 'Développé selon des normes microbiologiques strictes pour le contrôle de populations d\'insectes nuisibles spécifiques dans les programmes phytosanitaires.'),
(396, 'producto_especificaciones', 4, 'descripcion', 'ca', 'Desenvolupat sota estàndards microbiològics estrictes per al control de poblacions d\'insectes plaga específics en els programes fitosanitaris.'),
(397, 'producto_especificaciones', 5, 'titulo', 'en', 'Perfect integration into IPM strategies'),
(398, 'producto_especificaciones', 5, 'titulo', 'pt', 'Perfeita integração em estratégias IPM'),
(399, 'producto_especificaciones', 5, 'titulo', 'fr', 'Intégration parfaite dans les stratégies IPM'),
(400, 'producto_especificaciones', 5, 'titulo', 'ca', 'Perfecta integració en estratègies IPM'),
(401, 'producto_especificaciones', 5, 'descripcion', 'en', 'Compatible with integrated pest management guidelines and active ingredient rotation to prevent the development of resistance in the field.'),
(402, 'producto_especificaciones', 5, 'descripcion', 'pt', 'Compatível com as diretrizes de controle integrado e rotação de ingredientes ativos para prevenir o aparecimento de resistências no campo.'),
(403, 'producto_especificaciones', 5, 'descripcion', 'fr', 'Compatible avec les directives de lutte intégrée et la rotation des matières actives pour prévenir l\'apparition de résistances au champ.'),
(404, 'producto_especificaciones', 5, 'descripcion', 'ca', 'Compatible amb les pautes de control integrat i rotació de matèries actives per prevenir l\'aparició de resistències al camp.'),
(405, 'producto_especificaciones', 6, 'titulo', 'en', 'Easy-to-apply formulation'),
(406, 'producto_especificaciones', 6, 'titulo', 'pt', 'Formulação de fácil aplicação'),
(407, 'producto_especificaciones', 6, 'titulo', 'fr', 'Formulation facile à appliquer'),
(408, 'producto_especificaciones', 6, 'titulo', 'ca', 'Formulació de fàcil aplicació'),
(409, 'producto_especificaciones', 7, 'titulo', 'en', 'Purified double concentration'),
(410, 'producto_especificaciones', 7, 'titulo', 'pt', 'Dupla concentração purificada'),
(411, 'producto_especificaciones', 7, 'titulo', 'fr', 'Double concentration purifiée'),
(412, 'producto_especificaciones', 7, 'titulo', 'ca', 'Doble concentració depurada'),
(413, 'producto_especificaciones', 7, 'descripcion', 'en', 'Wettable powder biological insecticide formulated from an advanced strain of Bacillus thuringiensis at double concentration, providing greater potency and persistence.');
INSERT INTO `traducciones` (`id`, `tabla`, `traduccion_id`, `campo`, `idioma`, `texto`) VALUES
(414, 'producto_especificaciones', 7, 'descripcion', 'pt', 'Inseticida biológico em pó molhável formulado a partir de uma estirpe avançada de Bacillus thuringiensis em dupla concentração, proporcionando maior potência e persistência.'),
(415, 'producto_especificaciones', 7, 'descripcion', 'fr', 'Insecticide biologique en poudre mouillable formulé à partir d\'une souche avancée de Bacillus thuringiensis à double concentration, offrant une plus grande puissance et persistance.'),
(416, 'producto_especificaciones', 7, 'descripcion', 'ca', 'Insecticida biològic en pols mullable formulat a partir d\'una soca avançada de Bacillus thuringiensis a doble concentració, aportant major potència i persistència.'),
(417, 'producto_especificaciones', 8, 'titulo', 'en', 'Zero days safety pre-harvest interval'),
(418, 'producto_especificaciones', 8, 'titulo', 'pt', 'Zero dias de intervalo de segurança'),
(419, 'producto_especificaciones', 8, 'titulo', 'fr', 'Zéro jour de délai avant récolte'),
(420, 'producto_especificaciones', 8, 'titulo', 'ca', 'Zero dies de termini de seguretat'),
(421, 'producto_especificaciones', 8, 'descripcion', 'en', 'By leaving no type of chemical residue on the crops, it allows effective treatments to be carried out even up to the very day of harvest.'),
(422, 'producto_especificaciones', 8, 'descripcion', 'pt', 'Por não deixar nenhum tipo de resíduo químico nas colheitas, permite realizar tratamentos eficazes mesmo até o próprio dia da colheita.'),
(423, 'producto_especificaciones', 8, 'descripcion', 'fr', 'Ne laissant aucun type de résidu chimique sur les cultures, il permet d\'effectuer des traitements efficaces jusqu\'au jour même de la récolte.'),
(424, 'producto_especificaciones', 8, 'descripcion', 'ca', 'En no deixar cap tipus de residu químic a les collites, permet realitzar tractaments eficaços fins i tot fins al mateix dia de la recol·lecció.'),
(425, 'producto_especificaciones', 9, 'titulo', 'en', 'Ideal for organic farming'),
(426, 'producto_especificaciones', 9, 'titulo', 'pt', 'Ideal para agricultura biológica'),
(427, 'producto_especificaciones', 9, 'titulo', 'fr', 'Idéal pour l\'agriculture biologique'),
(428, 'producto_especificaciones', 9, 'titulo', 'ca', 'Ideal per a agricultura ecològica'),
(429, 'producto_especificaciones', 9, 'descripcion', 'en', 'Designed for the rigorous control of caterpillars and defoliating or fruit-eating lepidoptera in a very wide variety of horticultural, fruit, and woody crops.'),
(430, 'producto_especificaciones', 9, 'descripcion', 'pt', 'Concebido para o controlo rigoroso de lagartas e lepidópteros desfolhadores ou frutícolas numa larguíssima variedade de culturas hortícolas, fruteiras e lenhosas.'),
(431, 'producto_especificaciones', 9, 'descripcion', 'fr', 'Conçu pour le contrôle rigoureux des chenilles et des lépidoptères défoliateurs ou carpophages dans une très grande variété de cultures maraîchères, fruitières et ligneuses.'),
(432, 'producto_especificaciones', 9, 'descripcion', 'ca', 'Dissenyat per al control rigorós d\'orugues i lepidòpters desfulladors o fructícoles en una amplíssima varietat de cultius hortícoles, fruiters i llenyosos.'),
(433, 'producto_especificaciones', 10, 'titulo', 'en', 'Advanced borated nutrition'),
(434, 'producto_especificaciones', 10, 'titulo', 'pt', 'Nutrição boratada avançada'),
(435, 'producto_especificaciones', 10, 'titulo', 'fr', 'Nutrition boronée avancée'),
(436, 'producto_especificaciones', 10, 'titulo', 'ca', 'Nutrició boratada avançada'),
(437, 'producto_especificaciones', 10, 'descripcion', 'en', 'Liquid formulation based on boron complexed with ethanolamine, designed to optimize the absorption of the nutrient as boric acid directly into plant tissues.'),
(438, 'producto_especificaciones', 10, 'descripcion', 'pt', 'Formulação líquida à base de boro complexado com etanolamina, concebida para otimizar a absorção do nutriente como ácido bórico diretamente nos tecidos vegetais.'),
(439, 'producto_especificaciones', 10, 'descripcion', 'fr', 'Formulation liquide à base de bore complexé avec de l\'éthanolamine, conçue pour optimiser l\'absorption du nutriment sous forme d\'acide borique directement dans les tissus végétaux.'),
(440, 'producto_especificaciones', 10, 'descripcion', 'ca', 'Formulació líquida a base de bori acomplexat amb etanolamina, dissenyada per optimitzar l\'absorció del nutrient com a àcid bòric directament als teixits vegetals.'),
(441, 'producto_especificaciones', 11, 'titulo', 'en', 'Flowering and fruit set stimulation'),
(442, 'producto_especificaciones', 11, 'titulo', 'pt', 'Estímulo de floração e vingamento de frutos'),
(443, 'producto_especificaciones', 11, 'titulo', 'fr', 'Stimulation de la floraison et de nouaison'),
(444, 'producto_especificaciones', 11, 'titulo', 'ca', 'Estímul de floració i quallat'),
(445, 'producto_especificaciones', 11, 'descripcion', 'en', 'It directly intervenes in meristematic growth, promoting optimal fertilization, regulating cell division, and preventing malformations in shoots, flowers, and fruits.'),
(446, 'producto_especificaciones', 11, 'descripcion', 'pt', 'Intervém de forma direta no crescimento meristemático, promovendo a fertilização ótima, regulando a divisão celular e prevenindo malformações em brotos, flores e frutos.'),
(447, 'producto_especificaciones', 11, 'descripcion', 'fr', 'Il intervient directement dans la croissance méristématique, en favorisant une fertilisation optimale, en régulant la division cellulaire et en prévenant les malformations sur les pousses, les fleurs et les fruits.'),
(448, 'producto_especificaciones', 11, 'descripcion', 'ca', 'Intervé de manera directa en el creixement meristemàtic, promovent la fecundació òptima, regulant la divisió cel·lular i prevencent malformacions en brots, flors i fruits.'),
(449, 'producto_especificaciones', 12, 'titulo', 'en', 'Suitable for organic farming'),
(450, 'producto_especificaciones', 12, 'titulo', 'pt', 'Adequado para agricultura biológica'),
(451, 'producto_especificaciones', 12, 'titulo', 'fr', 'Convient à l\'agriculture biologique'),
(452, 'producto_especificaciones', 12, 'titulo', 'ca', 'Apte per a agricultura ecològica'),
(453, 'producto_especificaciones', 12, 'descripcion', 'en', 'Certified and integrated product for use in organic production systems, ensuring maximum safety and respect for the physiological development of the crop.'),
(454, 'producto_especificaciones', 12, 'descripcion', 'pt', 'Produto certificado e integrado para utilização em sistemas de produção biológica, garantindo a máxima segurança e respeito pelo desenvolvimento fisiológico da cultura.'),
(455, 'producto_especificaciones', 12, 'descripcion', 'fr', 'Produit certifié et intégré pour une utilisation dans les systèmes de production biologique, garantissant une sécurité maximale et le respect du développement physiologique de la culture.'),
(456, 'producto_especificaciones', 12, 'descripcion', 'ca', 'Producte certificat i integrat per al seu ús en sistemes de producció ecològica, garantint la màxima seguretat i respecte pel desenvolupament fisiològic del cultiu.'),
(457, 'producto_especificaciones', 13, 'titulo', 'en', 'Exclusive strain bioinsecticide'),
(458, 'producto_especificaciones', 13, 'titulo', 'pt', 'Bioinseticida de estirpe exclusiva'),
(459, 'producto_especificaciones', 13, 'titulo', 'fr', 'Bio-insecticide à souche exclusive'),
(460, 'producto_especificaciones', 13, 'titulo', 'ca', 'Bioinsecticida de soca exclusiva'),
(461, 'producto_especificaciones', 13, 'descripcion', 'en', 'Based on BASF\'s exclusive Beauveria bassiana strain PPRI 5339, it offers high intrinsic efficacy and great infection capacity by direct contact with the insect cuticle.'),
(462, 'producto_especificaciones', 13, 'descripcion', 'pt', 'Baseado na estirpe exclusiva PPRI 5339 de Beauveria bassiana da BASF, oferece alta eficácia intrínseca e grande capacidade de infeção por contacto direto sobre a cutícula do inseto.'),
(463, 'producto_especificaciones', 13, 'descripcion', 'fr', 'Basé sur la souche exclusive PPRI 5339 de Beauveria bassiana de BASF, il offre une haute efficacité intrinsèque et une grande capacité d\'infection par contact direct sur la cuticule de l\'insecte.'),
(464, 'producto_especificaciones', 13, 'descripcion', 'ca', 'Basat en l\'exclusiva soca PPRI 5339 de Beauveria bassiana de BASF, ofereix una alta eficàcia intrínseca i gran capacitat d\'infecció per contacte directe sobre la cutícula de l\'insecte.'),
(465, 'producto_especificaciones', 14, 'titulo', 'en', 'Effective control of whitefly and thrips'),
(466, 'producto_especificaciones', 14, 'titulo', 'pt', 'Controlo eficaz de mosca-branca e tripes'),
(467, 'producto_especificaciones', 14, 'titulo', 'fr', 'Contrôle efficace de l\'aleurode et des thrips'),
(468, 'producto_especificaciones', 14, 'titulo', 'ca', 'Control eficaç de mosca blanca i trips'),
(469, 'producto_especificaciones', 14, 'descripcion', 'en', 'Biological solution specialized in persistently reducing populations of thrips and whitefly in protected, horticultural, and ornamental crops.'),
(470, 'producto_especificaciones', 14, 'descripcion', 'pt', 'Solução biológica especializada em reduzir de forma persistente as populações de tripes e mosca-branca em culturas protegidas, hortícolas e ornamentais.'),
(471, 'producto_especificaciones', 14, 'descripcion', 'fr', 'Solution biologique spécialisée dans la réduction persistante des populations de thrips et d\'aleurodes dans les cultures protégées, maraîchères et ornementales.'),
(472, 'producto_especificaciones', 14, 'descripcion', 'ca', 'Solució biològica especialista a reduir de manera persistent les poblacions de trips i mosca blanca en cultius protegits, hortícoles i ornamentals.'),
(473, 'producto_especificaciones', 15, 'titulo', 'en', 'Compatible with integrated pest management and zero residue'),
(474, 'producto_especificaciones', 15, 'titulo', 'pt', 'Compatível com gestão integrada e resíduo zero'),
(475, 'producto_especificaciones', 15, 'titulo', 'fr', 'Compatible avec la gestion intégrée et zéro résidu'),
(476, 'producto_especificaciones', 15, 'titulo', 'ca', 'Compatible amb gestió integrada i residu zero'),
(477, 'producto_especificaciones', 15, 'descripcion', 'en', 'Its advanced formulation respects beneficial fauna and pollinators, helping to minimize chemical residues in the harvest and complying with food chain standards.'),
(478, 'producto_especificaciones', 15, 'descripcion', 'pt', 'A sua formulação avançada respeita a fauna auxiliar e os polinizadores, ajudando a minimizar os resíduos químicos na colheita e cumprindo os padrões da cadeia alimentar.'),
(479, 'producto_especificaciones', 15, 'descripcion', 'fr', 'Sa formulation avancée respecte la faune auxiliaire et les pollinisateurs, contribuant à minimiser les résidus chimiques dans la récolte et à respecter les normes de la chaîne alimentaire.'),
(480, 'producto_especificaciones', 15, 'descripcion', 'ca', 'La seva formulació avançada respecta la fauna auxiliar i els pol·linitzadors, ajudant a minimitzar els residus químics a la collita i complint els estàndards de la cadena alimentària.'),
(481, 'producto_especificaciones', 16, 'titulo', 'en', 'Powerful knock-down effect'),
(482, 'producto_especificaciones', 16, 'titulo', 'pt', 'Potente efeito de choque (Knock down)'),
(483, 'producto_especificaciones', 16, 'titulo', 'fr', 'Puissant effet de choc (Knock-down)'),
(484, 'producto_especificaciones', 16, 'titulo', 'ca', 'Potent efecte de xoc (Knock down)'),
(485, 'producto_especificaciones', 16, 'descripcion', 'en', 'Natural agricultural insecticide that causes rapid elimination and knockdown of pest insect populations after application.'),
(486, 'producto_especificaciones', 16, 'descripcion', 'pt', 'Inseticida agrícola natural que provoca uma rápida eliminação e desativação das populações de insetos praga após a sua aplicação.'),
(487, 'producto_especificaciones', 16, 'descripcion', 'fr', 'Insecticide agricole naturel qui provoque une élimination rapide et une neutralisation des populations d\'insectes nuisibles après application.'),
(488, 'producto_especificaciones', 16, 'descripcion', 'ca', 'Insecticida agrícola natural que provoca una ràpida eliminació i desactivació de les poblacions d\'insectes plaga després de la seva aplicació.'),
(489, 'producto_especificaciones', 17, 'titulo', 'en', 'Control of aphids, whiteflies, and leafhoppers'),
(490, 'producto_especificaciones', 17, 'titulo', 'pt', 'Controlo de afídeos, mosca-branca e cicadelídeos'),
(491, 'producto_especificaciones', 17, 'titulo', 'fr', 'Contrôle des pucerons, des aleurodes et des cicadelles'),
(492, 'producto_especificaciones', 17, 'titulo', 'ca', 'Control de pugó, mosca blanca i cicadèl·lids'),
(493, 'producto_especificaciones', 17, 'descripcion', 'en', 'Wide spectrum of highly effective action against soft-bodied insects such as whitefly, aphids, and green leafhopper in grapevine and horticultural crops.'),
(494, 'producto_especificaciones', 17, 'descripcion', 'pt', 'Amplo espetro de ação altamente eficaz contra insetos de corpo mole como mosca-branca, afídeos e cigarrinha-verde na videira e culturas hortícolas.'),
(495, 'producto_especificaciones', 17, 'descripcion', 'fr', 'Large spectre d\'action hautement efficace contre les insectes à corps mou tels que l\'aleurode, les pucerons et la cicadelle verte dans la vigne et les cultures maraîchères.'),
(496, 'producto_especificaciones', 17, 'descripcion', 'ca', 'Ampli espectre d\'acció altament eficaç enfront d\'insectes de cos tou com mosca blanca, pugons i mosquitu verd en vinya i hortícoles.'),
(497, 'producto_especificaciones', 18, 'titulo', 'en', '100% Natural without long safety intervals'),
(498, 'producto_especificaciones', 18, 'titulo', 'pt', '100% Natural sem prazos de segurança longos'),
(499, 'producto_especificaciones', 18, 'titulo', 'fr', '100% Naturel sans délais de sécurité prolongés'),
(500, 'producto_especificaciones', 18, 'titulo', 'ca', '100% Natural sense terminis de seguretat amplis'),
(501, 'producto_especificaciones', 18, 'descripcion', 'en', 'Patented formulation based on plant extracts with no chemical residue or PBO, allowing treatments very close to the time of harvest.'),
(502, 'producto_especificaciones', 18, 'descripcion', 'pt', 'Formulação patentiada à base de extratos vegetais sem resíduo químico nem PBO, permitindo realizar tratamentos muito próximos do momento da colheita.'),
(503, 'producto_especificaciones', 18, 'descripcion', 'fr', 'Formulation brevetée à base d\'extraits végétaux sans résidu chimique ni PBO, permettant d\'effectuer des traitements très près du moment de la récolte.'),
(504, 'producto_especificaciones', 18, 'descripcion', 'ca', 'Formulació patentada a base d\'extractes vegetals sense residu químic ni PBO, permetent realitzar tractaments molt pròxims al moment de la recol·lecció.'),
(505, 'producto_especificaciones', 19, 'titulo', 'en', 'High persistence anti-powdery mildew fungicide'),
(506, 'producto_especificaciones', 19, 'titulo', 'pt', 'Fungicida anti-oídio de alta persistência'),
(507, 'producto_especificaciones', 19, 'titulo', 'fr', 'Fongicide anti-oïdium à haute persistance'),
(508, 'producto_especificaciones', 19, 'titulo', 'ca', 'Fungicida anti-oïdi d\'alta persistència'),
(509, 'producto_especificaciones', 19, 'descripcion', 'en', 'Specialty based on Cyflufenamid 10% with preventive, curative, translaminar activity, and vapor effect for long-lasting control.'),
(510, 'producto_especificaciones', 19, 'descripcion', 'pt', 'Especialidade à base de Ciflufenamida 10% com atividade preventiva, curativa, translaminar e efeito vapor para um controlo duradouro.'),
(511, 'producto_especificaciones', 19, 'descripcion', 'fr', 'Spécialité à base de Cyflufénamide 10% avec une activité préventive, curative, translaminaire et un effet vapeur pour un contrôle durable.'),
(512, 'producto_especificaciones', 19, 'descripcion', 'ca', 'Especialitat a base de Ciflufenamid 10% amb activitat preventiva, curativa, translaminar i efecte vapor per a un control durador.'),
(513, 'producto_especificaciones', 20, 'titulo', 'en', 'New anti-resistance chemical family'),
(514, 'producto_especificaciones', 20, 'titulo', 'pt', 'Nova família química antirresistências'),
(515, 'producto_especificaciones', 20, 'titulo', 'fr', 'Nouvelle famille chimique anti-résistance'),
(516, 'producto_especificaciones', 20, 'titulo', 'ca', 'Nova família química antirresistències'),
(517, 'producto_especificaciones', 20, 'descripcion', 'en', 'It acts by altering the formation of haustoria and fungal sporulation, constituting an excellent tool in rotation to prevent resistance.'),
(518, 'producto_especificaciones', 20, 'descripcion', 'pt', 'Atua alterando a formação de haustórios e a esporulação do fungo, constituindo uma excelente ferramenta em rotação para evitar resistências.'),
(519, 'producto_especificaciones', 20, 'descripcion', 'fr', 'Il agit en altérant la formation des haustoria et la sporulation du champignon, constituant un excellent outil en rotation pour éviter les résistances.'),
(520, 'producto_especificaciones', 20, 'descripcion', 'ca', 'Actua alterant la formació d\'haustoris i esporulació del fong, constituint una eina excel·lent en rotació per evitar resistències.'),
(521, 'producto_especificaciones', 21, 'titulo', 'en', 'Zero Crop and Minimum Residue Range'),
(522, 'producto_especificaciones', 21, 'titulo', 'pt', 'Gama Cultivo Zero e Resíduo Mínimo'),
(523, 'producto_especificaciones', 21, 'titulo', 'fr', 'Gamme Culture Zéro et Résidu Minimum'),
(524, 'producto_especificaciones', 21, 'titulo', 'ca', 'Gamma Cultiu Zero i Residu Mínim'),
(525, 'producto_especificaciones', 21, 'descripcion', 'en', 'It stands out for its rapid degradation profile, short safety interval, and total compatibility with beneficial insects and pollinators.'),
(526, 'producto_especificaciones', 21, 'descripcion', 'pt', 'Destaca-se pelo seu perfil de degradação rápido, curto prazo de segurança e total compatibilidade com insetos auxiliares e polinizadores.'),
(527, 'producto_especificaciones', 21, 'descripcion', 'fr', 'Il se distingue par son profil de dégradation rapide, son court délai de sécurité et sa compatibilité totale avec les insectes auxiliaires et les pollinisateurs.'),
(528, 'producto_especificaciones', 21, 'descripcion', 'ca', 'Destaca pel seu perfil de degradació ràpid, curt termini de seguretat i total compatibilitat amb insectes auxiliars i pol·linitzadors.'),
(529, 'producto_especificaciones', 22, 'titulo', 'en', 'Innovative soil prebiotic'),
(530, 'producto_especificaciones', 22, 'titulo', 'pt', 'Prebiótico inovador para o solo'),
(531, 'producto_especificaciones', 22, 'titulo', 'fr', 'Prébiotique innovateur pour le sol'),
(532, 'producto_especificaciones', 22, 'titulo', 'ca', 'Innovador prebiòtic per al sòl'),
(533, 'producto_especificaciones', 22, 'descripcion', 'en', 'Advanced formulation of biotechnological origin designed to selectively stimulate beneficial native microbiota and enhance the soil microbiome.'),
(534, 'producto_especificaciones', 22, 'descripcion', 'pt', 'Formulado avançado de origem biotecnológica concebido para estimular de forma seletiva a microbiota nativa benéfica e potenciar o microbioma do solo.'),
(535, 'producto_especificaciones', 22, 'descripcion', 'fr', 'Formulation avancée d\'origine biotechnologique conçue pour stimuler sélectivement le microbiote indigène bénéfique et valoriser le microbiome du sol.'),
(536, 'producto_especificaciones', 22, 'descripcion', 'ca', 'Formulat avançat d\'origen biotecnològic dissenyat per estimular de manera selectiva la microbiota nativa benèfica i potenciar el microbioma del sòl.'),
(537, 'producto_especificaciones', 23, 'titulo', 'en', 'Pioneer in regenerative agriculture'),
(538, 'producto_especificaciones', 23, 'titulo', 'pt', 'Pioneiro em agricultura regenerativa'),
(539, 'producto_especificaciones', 23, 'titulo', 'fr', 'Pionnier de l\'agriculture régénérative'),
(540, 'producto_especificaciones', 23, 'titulo', 'ca', 'Pioner en agricultura regenerativa'),
(541, 'producto_especificaciones', 23, 'descripcion', 'en', 'Recognized for its ability to reactivate biological fertility and the productive structure of degraded agricultural soils.'),
(542, 'producto_especificaciones', 23, 'descripcion', 'pt', 'Reconhecido pela sua capacidade de reativar a fertilidade biológica e a estrutura produtiva dos solos agrícolas degradados.'),
(543, 'producto_especificaciones', 23, 'descripcion', 'fr', 'Reconnu pour sa capacité à réactiver la fertilité biologique et la structure productive des sols agricoles dégradés.'),
(544, 'producto_especificaciones', 23, 'descripcion', 'ca', 'Reconegut per la seva capacitat de reactivar la fertilitat biològica i l\'estructura productiva dels sòls agrícoles degradats.'),
(545, 'producto_especificaciones', 24, 'titulo', 'en', 'Systemic resistance and biotic stress'),
(546, 'producto_especificaciones', 24, 'titulo', 'pt', 'Resistência sistémica e stress biótico'),
(547, 'producto_especificaciones', 24, 'titulo', 'fr', 'Résistance systémique et stress biotique'),
(548, 'producto_especificaciones', 24, 'titulo', 'ca', 'Resistència sistèmica i estrès biòtic'),
(549, 'producto_especificaciones', 24, 'descripcion', 'en', 'Helps crops tolerate and mitigate complex phytopathological conditions, improving the plant\'s natural resilience against viruses and pathogens.'),
(550, 'producto_especificaciones', 24, 'descripcion', 'pt', 'Ajuda as culturas a tolerar e mitigar afecções fitopatológicas complexas, melhorando a resiliência natural da planta face a vírus e patogénios.'),
(551, 'producto_especificaciones', 24, 'descripcion', 'fr', 'Aide les cultures à tolérer et à atténuer les affections phytopathologiques complexes, en améliorant la résilience naturelle de la plante face aux virus et aux agents pathogènes.'),
(552, 'producto_especificaciones', 24, 'descripcion', 'ca', 'Ajuda els cultius a tolerar i mitigar afeccions fitopatològiques complexes, millorant la resiliència natural de la planta enfront de virus i patògens.'),
(553, 'producto_especificaciones', 25, 'titulo', 'en', 'Ultra-fast acting potassium corrector'),
(554, 'producto_especificaciones', 25, 'titulo', 'pt', 'Corretor potássico de ação ultra-rápida'),
(555, 'producto_especificaciones', 25, 'titulo', 'fr', 'Correcteur potassique à action ultra-rapide'),
(556, 'producto_especificaciones', 25, 'titulo', 'ca', 'Corrector potàssic d\'acció ultra ràpida'),
(557, 'producto_especificaciones', 25, 'descripcion', 'en', 'Source of potassium with maximum immediate availability for the crop, formulated to cover peaks of high nutritional demand.'),
(558, 'producto_especificaciones', 25, 'descripcion', 'pt', 'Fonte de potássio de máxima disponibilidade imediata para a cultura, formulada para cobrir picos de alta procura nutricional.'),
(559, 'producto_especificaciones', 25, 'descripcion', 'fr', 'Source de potassium à disponibilité immédiate maximale pour la culture, formulée pour couvrir les pics de forte demande nutritionnelle.'),
(560, 'producto_especificaciones', 25, 'descripcion', 'ca', 'Font de potassi de màxima disponibilitat immediata per al cultiu, formulada per cobrir pics d\'alta demanda nutricional.'),
(561, 'producto_especificaciones', 26, 'titulo', 'en', 'Special for ripening and sizing'),
(562, 'producto_especificaciones', 26, 'titulo', 'pt', 'Especial para maturação e engorda'),
(563, 'producto_especificaciones', 26, 'titulo', 'fr', 'Spécial pour la maturation et le grossissement'),
(564, 'producto_especificaciones', 26, 'titulo', 'ca', 'Especial per a maduració i engreix'),
(565, 'producto_especificaciones', 26, 'descripcion', 'en', 'Naturally accelerates the processes of sugar accumulation, coloration, size, and optimal fruit consistency.'),
(566, 'producto_especificaciones', 26, 'descripcion', 'pt', 'Aceita de forma natural os processos de acumulação de açúcares, coloração, tamanho e consistência ótima dos frutos.'),
(567, 'producto_especificaciones', 26, 'descripcion', 'fr', 'Accélère naturellement les processus d\'accumulation des sucres, de coloration, de taille et de consistance optimale des fruits.'),
(568, 'producto_especificaciones', 26, 'descripcion', 'ca', 'Accelera de manera natural els processos d\'acumulació de sucres, coloració, mida i consistència òptima dels fruits.'),
(569, 'producto_especificaciones', 27, 'titulo', 'en', 'Osmotic and water efficiency'),
(570, 'producto_especificaciones', 27, 'titulo', 'pt', 'Eficiência osmótica e hídrica'),
(571, 'producto_especificaciones', 27, 'titulo', 'fr', 'Efficacité osmotique et hydrique'),
(572, 'producto_especificaciones', 27, 'titulo', 'ca', 'Eficiència osmòtica i hídrica'),
(573, 'producto_especificaciones', 27, 'descripcion', 'en', 'Improves stomatal regulation and internal water management, providing the crop with greater resistance against drought or salinity.'),
(574, 'producto_especificaciones', 27, 'descripcion', 'pt', 'Melhora a regulação dos estomas e a gestão interna da água, conferindo à cultura maior resistência face à seca ou salinidade.'),
(575, 'producto_especificaciones', 27, 'descripcion', 'fr', 'Améliore la régulation stomatique et la gestion interne de l\'eau, conférant à la culture une plus grande résistance contre la sécheresse ou la salinité.'),
(576, 'producto_especificaciones', 27, 'descripcion', 'ca', 'Millora la regulació dels estomes i la gestió interna de l\'aigua, dotant el cultiu d\'una major resistència enfront de la sequia o salinitat.'),
